    <h3>{title}</h3>
  {:else if type === 'error'}
    <p>Oops, something went wrong.</p>
  {:else if type === 'warning'}
    <p>Be careful!</p>
  {:else}
    <p>{message}</p>
  {/if}
  <button onclick={() => (shown = false)} aria-label="Dismiss" class={shown ? 'hidden' : ''}>✕</button>
</div>

{#if dismissable && shown}
  <script>
    export let onDismiss;
    export let onClose = () => {
      if (onDismiss) onDismiss();
      shown = false;
    };
  </script>
{/if}

