<script>
  export let duration = 0;
  let timer;
  let started = $state(false);
  let elapsed = $derived(started ? Math.floor(duration / 1000) : 0);

  function start() {
    if (started) return;
    timer = setInterval(() => (duration += 10), 10);
    started = true;
  }
  function stop() {
    clearInterval(timer);
    started = false;
  }
</script>

<div class="stopwatch">
  <p>{elapsed} s</p>
  <button onclick={started ? stop : start}>Start / Pause</button>
  <button disabled={!started} onclick={() => (duration = 0)}>Reset</button>
</div>

<style>
  .stopwatch { font-family: sans-serif; }
  button { margin-left: 8px; }
</style>
